#include "lcdinterface.h"


// bind this class's _tft to object defined in main for gfx
LcdInterface::LcdInterface(TFT_eSPI& tft) : _tft(tft){}


void LcdInterface::begin()
{
  _tft.init(); 
  _tft.setRotation(3);
  _tft.fillScreen(TFT_BLACK);
}
void LcdInterface::pushImage(int32_t x, int32_t y, int32_t w, int32_t h, const uint16_t *data)
{
  _tft.pushImage(x, y, w, h, data);
}
void LcdInterface::drawBlackRect(int32_t x, int32_t y, int32_t w, int32_t h)
{
  _tft.fillRect(x, y, w, h, TFT_BLACK);
}
